style.css:
/* Simple Dark Mode for Google – Stylish version */
/* Works on google.com, google.ca, etc. */

html, body {
  background-color: #000 !important;
  color: #fff !important;
}

/* Make sure images and logos stay normal */
img, video, image, svg, svg * {
  filter: none !important;
  mix-blend-mode: normal !important;
}

/* Search result titles and text */
a, h1, h2, h3, h4, h5, h6, span, div, p {
  color: #fff !important;
  background-color: transparent !important;
}

/* Search box */
input, textarea {
  background-color: #111 !important;
  color: #fff !important;
  border: 1px solid #333 !important;
}

/* Result cards / boxes */
.g, .MjjYud, .mnr-c {
  background-color: #000 !important;
  color: #fff !important;
  border: none !important;
}

/* Footer and header */
#fbar, #fsl, header, footer {
  background-color: #000 !important;
  color: #888 !important;
}

/* Scrollbar for a dark look */
*::-webkit-scrollbar { width: 10px; }
*::-webkit-scrollbar-track { background: #000; }
*::-webkit-scrollbar-thumb {
  background: #333;
  border-radius: 10px;
}
*::-webkit-scrollbar-thumb:hover { background: #555; }
